  constructor(args: TsClassPropertyArgs) {
    this.name = args.name
    this.type = args.type
    this.value = args.value
    this.isOptional = args.optional ?? false
    this.isReadonly = args.readonly ?? false
    this.isStatic = args.static ?? false
    this.accessibility = args.accessibility
