1	#!/usr/bin/env node
2	// Proto-B1 (H3 gate, notes/skills-tools/PLAN.md): per-subject view over a
3	// `skmtc generate --debug` capture. Ground-truths what the capture can
4	// show — value tree, imports, definitions, rendered text — and, by
5	// omission, what it cannot (per-lookup cache hit/miss, event ordering:
6	// those belong to B3's trace).
7	//
8	// Usage: node proto-inspect-subject.mjs <capture.json> <generator-id> <subject>
9	//   subject matches any generatorKey segment (model refName, or op path/method)
10	
11	import { readFileSync } from 'node:fs'
12	
13	const [capturePath, generatorId, subject] = process.argv.slice(2)
14	if (!capturePath || !generatorId || !subject) {
15	  console.error('usage: proto-inspect-subject.mjs <capture.json> <generator-id> <subject>')
16	  process.exit(1)
17	}
18	
19	const { artifacts, inspection } = JSON.parse(readFileSync(capturePath, 'utf8'))
20	
21	const SKIP_KEYS = new Set(['settings', 'operation', 'context', 'stackTrail', 'skipped', '__class', 'generatorKey'])
22	const MAX_DEPTH = 6
23	
24	const isNode = value => value !== null && typeof value === 'object'
25	
26	const shortJson = value => {
27	  const text = JSON.stringify(value)
28	  return text.length > 80 ? `${text.slice(0, 77)}…` : text
29	}
30	
31	const printTree = (node, indent, depth, ownerKey) => {
32	  if (!isNode(node)) return console.log(`${indent}${shortJson(node)}`)
33	
34	  if (node.__class === 'Map') {
35	    for (const [key, child] of Object.entries(node)) {
36	      if (key === '__class') continue
37	      console.log(`${indent}${key}:`)
38	      printTree(child, indent + '  ', depth + 1, ownerKey)
39	    }
40	    return
41	  }
42	
43	  if (Array.isArray(node)) {
44	    node.forEach(child => printTree(child, indent, depth, ownerKey))
45	    return
46	  }
47	
48	  if (node.__class) {
